package store

import (
	"context"
	"database/sql"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/access"
)

// TestLedgerWritesStampViewer pins 5.1's write contract (l6-accounts D7):
// both ledger WRITES stamp THE VIEWER — PutProgress upserts into (v.UserID,
// item_id) and InsertWatched stamps v.UserID — so two users' writes to one
// item are independent rows, a per-slot re-put/rewatch never bleeds into
// another user's row, and every legacy principal (System, Admin,
// LegacyDevice, the zero Viewer — all UserID 0 by construction) writes the
// user_id=0 legacy slot. Slot-level assertions read slots via direct SQL —
// the scoped READS carry the own-slot conjunct (5.2), so a slot write is
// provable through them only by that same slot's viewer.
func TestLedgerWritesStampViewer(t *testing.T) {
	s := openStore(t)
	ctx := context.Background()
	seed := seedViewerWorld(t, s)
	itemID := "Show.A/ep1.mkv"
	vA := access.User(1, []int64{seed.libA}, nil)
	vB := access.User(2, []int64{seed.libA}, nil)

	progressSlotPos := func(userID int64) (int64, bool) {
		t.Helper()
		var pos int64
		err := s.db.QueryRowContext(ctx,
			"SELECT position_seconds FROM playback_progress WHERE user_id = ? AND item_id = ?",
			userID, itemID).Scan(&pos)
		if err == sql.ErrNoRows {
			return 0, false
		}
		if err != nil {
			t.Fatalf("read progress slot %d: %v", userID, err)
		}
		return pos, true
	}
	watchedSlotStamp := func(userID int64, wantItem string) (time.Time, bool) {
		t.Helper()
		var stamp string
		err := s.db.QueryRowContext(ctx,
			"SELECT completed_at FROM watched_items WHERE user_id = ? AND item_id = ?",
			userID, wantItem).Scan(&stamp)
		if err == sql.ErrNoRows {
			return time.Time{}, false
		}
		if err != nil {
			t.Fatalf("read watched slot %d for %s: %v", userID, wantItem, err)
		}
		done, err := parseTime(stamp)
		if err != nil {
			t.Fatalf("parse watched slot %d stamp %s: %v", userID, stamp, err)
		}
		return done, true
	}

	t.Run("two_users_one_item_two_rows", func(t *testing.T) {
		if _, err := s.PutProgress(ctx, itemID, 60, vA); err != nil {
			t.Fatalf("PutProgress(user A): %v", err)
		}
		if _, err := s.PutProgress(ctx, itemID, 60, vB); err != nil {
			t.Fatalf("PutProgress(user B): %v", err)
		}
		posA, okA := progressSlotPos(1)
		if !okA {
			t.Fatalf("user A's slot for %s missing after A's put", itemID)
		}
		posB, okB := progressSlotPos(2)
		if !okB {
			t.Fatalf("user B's slot for %s missing after B's put", itemID)
		}
		if posA != 60 || posB != 60 {
			t.Fatalf("slots hold (%d, %d), want (60, 60) — same visible values, independent rows", posA, posB)
		}
	})

	t.Run("put_upsert_conflicts_per_slot", func(t *testing.T) {
		if _, err := s.PutProgress(ctx, itemID, 90, vA); err != nil {
			t.Fatalf("PutProgress(user A) re-put: %v", err)
		}
		posA, ok := progressSlotPos(1)
		if !ok || posA != 90 {
			t.Fatalf("user A's slot = (%v, %v), want (90, true) after the re-put", posA, ok)
		}
		posB, ok := progressSlotPos(2)
		if !ok || posB != 60 {
			t.Fatalf("user B's slot = (%v, %v), want (60, true) — untouched by A's re-put", posB, ok)
		}
		// The legacy slot never saw a write here.
		if _, ok := progressSlotPos(0); ok {
			t.Fatalf("slot 0 unexpectedly holds a row for %s (no legacy write issued)", itemID)
		}
	})

	t.Run("insert_watched_stamps_user_slot", func(t *testing.T) {
		t0 := time.Date(2026, 11, 1, 12, 0, 0, 0, time.UTC)
		if err := s.InsertWatched(ctx, itemID, seed.libA, "", t0, vA); err != nil {
			t.Fatalf("InsertWatched(user A): %v", err)
		}
		done, ok := watchedSlotStamp(1, itemID)
		if !ok {
			t.Fatalf("user A's watched slot for %s missing after A's insert", itemID)
		}
		if !done.Equal(t0) {
			t.Fatalf("user A's watched slot completed_at = %v, want %v", done, t0)
		}
	})

	t.Run("rewatch_same_user_keeps_first_write", func(t *testing.T) {
		t1 := time.Date(2026, 11, 2, 12, 0, 0, 0, time.UTC)
		if err := s.InsertWatched(ctx, itemID, seed.libA, "", t1, vA); err != nil {
			t.Fatalf("InsertWatched(user A) rewatch: %v", err)
		}
		done, _ := watchedSlotStamp(1, itemID)
		if !done.Equal(time.Date(2026, 11, 1, 12, 0, 0, 0, time.UTC)) {
			t.Fatalf("rewatch by the SAME user moved completed_at to %v, want the first write kept", done)
		}
	})

	t.Run("rewatch_different_user_inserts_own_row", func(t *testing.T) {
		t2 := time.Date(2026, 11, 3, 12, 0, 0, 0, time.UTC)
		if err := s.InsertWatched(ctx, itemID, seed.libA, "", t2, vB); err != nil {
			t.Fatalf("InsertWatched(user B): %v", err)
		}
		doneB, ok := watchedSlotStamp(2, itemID)
		if !ok || !doneB.Equal(t2) {
			t.Fatalf("user B's watched slot = (%v, %v), want (%v, true)", doneB, ok, t2)
		}
		// B's insert must not have resurrected A's first-write window.
		doneA, ok := watchedSlotStamp(1, itemID)
		if !ok || !doneA.Equal(time.Date(2026, 11, 1, 12, 0, 0, 0, time.UTC)) {
			t.Fatalf("user A's watched slot = (%v, %v), want the first write untouched", doneA, ok)
		}
	})

	t.Run("legacy_viewers_write_slot_zero", func(t *testing.T) {
		// Progress: the three see-all principals all target (0, item) — the
		// upsert collapses them onto ONE legacy row, last writer wins.
		for name, v := range map[string]access.Viewer{
			"system": access.System(), "admin": access.Admin(), "legacy": access.LegacyDevice(),
		} {
			if _, err := s.PutProgress(ctx, itemID, 10, v); err != nil {
				t.Fatalf("PutProgress(%s): %v", name, err)
			}
		}
		pos, ok := progressSlotPos(0)
		if !ok || pos != 10 {
			t.Fatalf("legacy progress slot = (%v, %v), want (10, true)", pos, ok)
		}
		// Watched: no visibility check on this write, so even the zero Viewer
		// writes — a distinct item per legacy principal proves each stamps 0.
		legacyWatched := map[string]struct {
			v      access.Viewer
			itemID string
		}{
			"system": {access.System(), "w_sys"},
			"admin":  {access.Admin(), "w_admin"},
			"legacy": {access.LegacyDevice(), "w_legacy"},
			"zero":   {access.Viewer{}, "w_zero"},
		}
		at := time.Date(2026, 11, 1, 0, 0, 0, 0, time.UTC)
		for name, lw := range legacyWatched {
			if err := s.InsertWatched(ctx, lw.itemID, seed.libA, "", at, lw.v); err != nil {
				t.Fatalf("InsertWatched(%s): %v", name, err)
			}
			if _, ok := watchedSlotStamp(0, lw.itemID); !ok {
				t.Fatalf("legacy watched slot missing for %s (viewer %s wrote a foreign slot)", lw.itemID, name)
			}
		}
		// GetProgress(System) spans every slot pre-5.2, so the multi-slot item
		// reads ambiguously there (the own-slot conjunct is 5.2's) — the
		// legacy row itself is asserted via direct SQL above.
	})
}
